mapper.select:
SELECT m.matchId AS matchId, startTime, title, people, status, COUNT(mp.matchId) AS countPeople, t.tag, kategorie
FROM match_tbl m
INNER JOIN matchparticipant_tbl mp ON m.matchId = mp.matchId
LEFT JOIN matchtag_tbl t ON m.matchId = t.matchId
WHERE kategorie = #{type}
GROUP BY m.matchId, startTime, title, people, status, tag, kategorie;
